const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const directory = path.join(root, 'images', 'Logos');
const images = fs.existsSync(directory)
  ? fs.readdirSync(directory, { withFileTypes: true })
      .filter(entry => entry.isFile() && /\.(png|jpe?g|gif|webp|avif|svg|bmp|ico)$/i.test(entry.name))
      .map(entry => `images/Logos/${encodeURIComponent(entry.name)}`)
      .sort()
  : [];

fs.writeFileSync(path.join(root, 'assets', 'js', 'logo-images.js'),
  '// Generated by scripts/generate-logo-list.cjs.\n' +
  `window.siteLogoImages = ${JSON.stringify(images, null, 2)};\n`);
console.log(`Indexed ${images.length} logo images.`);
